import { tx, type JhsPreviewUnit } from './jhs-preview-units';

// Explicit authoring against pinned SCIENCE.pdf pages 41–52. Drafts remain hidden.
const unit = (page: number, row: number, value: Omit<JhsPreviewUnit, 'id'>): JhsPreviewUnit => ({
  id: `competency-gh-science-b7-nacca2020-p${String(page).padStart(3, '0')}-r${String(row).padStart(2, '0')}`, ...value,
});
export const B7_SCIENCE_FOUNDATIONS: JhsPreviewUnit[] = [
  unit(41, 1, {
    title: tx('Reading the periodic table', 'Lire le tableau périodique'),
    subskills: ['name-first-twenty-elements', 'classify-elements-from-table', 'explain-atomic-number-and-groups'],
    misconception: 'confuses-symbol-with-name-or-order',
    explanation: tx('The periodic table orders elements by increasing atomic number, not alphabetically. A symbol uses a capital first letter and, if present, a lower-case second letter: Co and CO are different writings. The first twenty are: 1 hydrogen H; 2 helium He; 3 lithium Li; 4 beryllium Be; 5 boron B; 6 carbon C; 7 nitrogen N; 8 oxygen O; 9 fluorine F; 10 neon Ne; 11 sodium Na; 12 magnesium Mg; 13 aluminium Al; 14 silicon Si; 15 phosphorus P; 16 sulfur S; 17 chlorine Cl; 18 argon Ar; 19 potassium K; 20 calcium Ca. Rows are periods; columns are groups. Elements in a group have related properties. Sodium and potassium are metals; oxygen and chlorine are non-metals; helium, neon and argon are noble gases. Boron and silicon are commonly labelled metalloids: do not force every element into only the three categories highlighted by the indicator.', 'Le tableau périodique classe les éléments par numéro atomique croissant, pas par ordre alphabétique. Un symbole commence par une majuscule suivie, si nécessaire, d’une minuscule. Les vingt premiers sont : 1 hydrogène H ; 2 hélium He ; 3 lithium Li ; 4 béryllium Be ; 5 bore B ; 6 carbone C ; 7 azote N ; 8 oxygène O ; 9 fluor F ; 10 néon Ne ; 11 sodium Na ; 12 magnésium Mg ; 13 aluminium Al ; 14 silicium Si ; 15 phosphore P ; 16 soufre S ; 17 chlore Cl ; 18 argon Ar ; 19 potassium K ; 20 calcium Ca. Les lignes sont des périodes, les colonnes des groupes. Un groupe réunit des propriétés apparentées. Sodium et potassium sont des métaux ; oxygène et chlore des non-métaux ; hélium, néon et argon des gaz nobles. Bore et silicium sont couramment classés comme métalloïdes : ne force pas tous les éléments dans seulement trois catégories.'),
    example: tx('Make cards for Na, Mg, Cl and Ar with atomic numbers 11, 12, 17 and 18. Arrange them as Na → Mg → Cl → Ar, preserving gaps for other elements. Na and Mg are metals, Cl a non-metal and Ar a noble gas. On a teacher-approved full table, locate Na and K in the same column and explain the distinction between a shared group and consecutive atomic numbers.', 'Fabrique des cartes Na, Mg, Cl et Ar portant 11, 12, 17 et 18. Range-les Na → Mg → Cl → Ar en laissant les places des autres éléments. Na et Mg sont métalliques, Cl non métallique et Ar un gaz noble. Sur un tableau complet approuvé, repère Na et K dans la même colonne et distingue groupe commun et numéros consécutifs.'),
    question: tx('Which rule determines the order of elements in the modern periodic table?', 'Quelle règle détermine l’ordre des éléments du tableau périodique moderne ?'),
    options: { en: ['Increasing atomic number', 'Alphabetical order of English names', 'The colour of a sample'], fr: ['Le numéro atomique croissant', 'L’ordre alphabétique des noms anglais', 'La couleur d’un échantillon'] },
    correction: tx('Read the atomic number, not the first letter. Hydrogen has 1 and helium 2, even though their alphabetical positions would differ. A column groups related properties; it is not the counting order. Reorder your cards by number and retry.', 'Lis le numéro atomique, pas la première lettre. Hydrogène porte 1 et hélium 2, indépendamment de l’alphabet. Une colonne rapproche des propriétés ; ce n’est pas l’ordre de comptage. Replace les cartes par numéro et réessaie.'),
    tasks: [tx('Independently write the names and correctly capitalised symbols of the first twenty elements in atomic-number order. On a teacher-approved table identify metals, non-metals and noble gases, mark any metalloid labels and explain one shared group. Your teacher must inspect the actual list and question your reasoning.', 'Écris seul les noms et symboles correctement composés des vingt premiers éléments dans l’ordre des numéros atomiques. Sur un tableau approuvé, repère métaux, non-métaux et gaz nobles, indique les métalloïdes éventuels et explique un groupe commun. L’enseignant examine la liste et interroge ton raisonnement.'), tx('Prepare and independently arrange twenty numbered element cards. Explain the symbol of sodium and potassium, classify representative metals/non-metals/noble gases and distinguish rows from columns. Show the real arrangement to your teacher.', 'Prépare vingt cartes numérotées et range-les seul. Explique les symboles du sodium et du potassium, classe des exemples de métaux/non-métaux/gaz nobles et distingue lignes et colonnes. Montre la vraie disposition à l’enseignant.')],
    transfer: [tx('A classmate alphabetised element cards. Independently identify and correct the ordering mistake, explain a same-group pair and use an approved table to check the symbols. Submit the corrected arrangement and reasoning.', 'Un camarade a classé les cartes par alphabet. Corrige seul ce classement, explique une paire du même groupe et vérifie les symboles dans un tableau approuvé. Présente l’arrangement corrigé et le raisonnement.'), tx('Using a new teacher-selected section of a periodic table, explain how you can infer order and groups without using alphabetical names. Separate what the table shows from properties needing another information source.', 'Avec une nouvelle partie du tableau choisie par l’enseignant, explique l’ordre et les groupes sans utiliser l’alphabet. Distingue les informations visibles des propriétés nécessitant une autre source.')],
    retention: [tx('Which symbol is potassium in the first twenty elements?', 'Quel symbole désigne le potassium parmi les vingt premiers éléments ?'), tx('Which pair belongs to the noble gases?', 'Quelle paire appartient aux gaz nobles ?')],
    retentionOptions: [{ en: ['K', 'P', 'Po'], fr: ['K', 'P', 'Po'] }, { en: ['Helium and neon', 'Sodium and magnesium', 'Carbon and oxygen'], fr: ['Hélium et néon', 'Sodium et magnésium', 'Carbone et oxygène'] }],
    criteria: [tx('Check all twenty names/symbols and order in the actual independent product, not just recognition of one option.', 'Vérifier les vingt noms/symboles et l’ordre dans le vrai travail autonome, pas seulement une réponse reconnue.'), tx('Check table-based category/group reasoning; preserve metalloid nuance and correct symbol case.', 'Vérifier les catégories et groupes à partir du tableau, la nuance des métalloïdes et la casse des symboles.')],
  }),
  unit(42, 1, {
    title: tx('An animal cell: structures and functions', 'La cellule animale : structures et fonctions'),
    subskills: ['identify-animal-cell-structures', 'explain-cell-functions', 'draw-and-model-animal-cell'], misconception: 'gives-animal-cell-a-cell-wall',
    explanation: tx('Animals are made of cells. A typical animal-cell diagram shows a cell membrane controlling exchange, cytoplasm where many reactions occur, a nucleus containing genetic information and controlling many cell activities, mitochondria releasing usable energy through respiration, and ribosomes making proteins. Animal cells do not have a plant cell wall or chloroplasts. Real cells differ in shape and specialisation; a textbook outline is a model. Use approved images of cells from different animal tissues, label what is actually shown, and relate each studied structure to its function. A normal hand magnifier cannot resolve all these organelles; do not invent observations.', 'Les animaux sont constitués de cellules. Un schéma typique montre une membrane qui contrôle les échanges, du cytoplasme où se déroulent de nombreuses réactions, un noyau contenant l’information génétique et contrôlant beaucoup d’activités, des mitochondries libérant de l’énergie utilisable par respiration et des ribosomes fabriquant les protéines. Les cellules animales n’ont ni paroi végétale ni chloroplastes. Les cellules réelles diffèrent selon leur spécialisation ; le contour du manuel est un modèle. Observe des images approuvées de différents tissus, légende ce qui est réellement montré et relie chaque structure étudiée à sa fonction. Une loupe ordinaire ne révèle pas tous ces organites ; n’invente aucune observation.'),
    example: tx('In a simplified drawing, label the boundary “membrane”, the inside “cytoplasm”, and a nucleus. Add mitochondria and ribosomes as schematic symbols with a key. Explain that symbol size and colours are not measured appearances. Compare with an approved cheek-cell image; record which structures can actually be distinguished, without collecting tissue yourself.', 'Sur un dessin simplifié, indique « membrane » au contour, « cytoplasme » à l’intérieur et un noyau. Ajoute des symboles de mitochondries et ribosomes avec une légende. Leurs dimensions et couleurs ne sont pas des mesures réelles. Compare une image approuvée de cellule buccale et note les structures réellement distinguables, sans prélever de tissu.'),
    question: tx('Which structure controls exchange across an animal cell boundary?', 'Quelle structure contrôle les échanges à la limite d’une cellule animale ?'),
    options: { en: ['Cell membrane', 'Plant cell wall', 'Chloroplast'], fr: ['La membrane cellulaire', 'La paroi végétale', 'Le chloroplaste'] },
    correction: tx('Separate the flexible cell membrane from a plant cell wall. An animal cell has a membrane; it has neither a plant wall nor chloroplasts. Trace the boundary on your drawing, explain exchange and retry.', 'Distingue membrane cellulaire et paroi végétale. Une cellule animale possède une membrane, mais ni paroi végétale ni chloroplastes. Repasse le contour du dessin, explique les échanges et réessaie.'),
    tasks: [tx('Inspect approved pictures/video of cells from two animal tissues and record the source. Independently draw and label an animal cell, explain each studied organelle and make a safe labelled paper/card model. Show actual work and distinguish observed details from schematic additions. Teacher inspection is required.', 'Observe des images ou une vidéo approuvées de deux tissus animaux et note la source. Dessine et légende seul une cellule, explique les organites étudiés et construis un modèle sûr en papier/carton. Montre le vrai travail et distingue détails observés et ajouts schématiques. Examen par l’enseignant requis.'), tx('With a different approved animal-cell image, identify visible structures, explain membrane/cytoplasm/nucleus/mitochondria/ribosome functions, draw a labelled diagram and present your independent model and its limitations to your teacher.', 'Avec une autre image approuvée, repère les structures visibles, explique membrane/cytoplasme/noyau/mitochondries/ribosomes, dessine un schéma légendé et présente ton modèle personnel et ses limites à l’enseignant.')],
    transfer: [tx('Evaluate a fictional animal-cell drawing containing a plant wall and chloroplasts. Independently correct it, explain each correction and compare it with a checked animal-cell image. Present the revised model.', 'Évalue un dessin fictif de cellule animale comportant paroi végétale et chloroplastes. Corrige-le seul, justifie les corrections et compare avec une image vérifiée. Présente le modèle corrigé.'), tx('Explain why differently shaped cells from two animal tissues still count as cells. Use approved images, actual labelled work and a structure-function explanation; do not claim every organelle is visible in every image.', 'Explique pourquoi deux cellules de tissus animaux de formes différentes restent des cellules. Utilise des images approuvées, ton vrai travail légendé et les relations structure-fonction ; ne prétends pas que tous les organites sont visibles.')],
    retention: [tx('Which organelle releases usable energy through respiration?', 'Quel organite libère de l’énergie utilisable par respiration ?'), tx('Which pair is absent from a typical animal cell?', 'Quelle paire est absente d’une cellule animale typique ?')],
    retentionOptions: [{ en: ['Mitochondrion', 'Plant cell wall', 'A drawn colour key'], fr: ['La mitochondrie', 'La paroi végétale', 'La légende colorée'] }, { en: ['Plant wall and chloroplasts', 'Membrane and cytoplasm', 'Nucleus and mitochondria'], fr: ['Paroi végétale et chloroplastes', 'Membrane et cytoplasme', 'Noyau et mitochondries'] }],
    criteria: [tx('Inspect actual drawing/model, source observations and independent structure-function explanations.', 'Examiner les vrais dessin/modèle, les observations documentées et les explications autonomes des fonctions.'), tx('Reject invented microscopy details or plant structures assigned to an animal cell; judge the limits of the chosen image/model.', 'Refuser les détails microscopiques inventés ou les structures végétales attribuées à une cellule animale ; vérifier les limites de l’image/modèle.')],
  }),
  unit(43, 1, {
    title: tx('Plant cells and their organelles', 'Cellules végétales et organites'),
    subskills: ['identify-plant-cell-structures', 'explain-plant-cell-functions', 'draw-and-model-plant-cell'], misconception: 'assumes-every-plant-cell-has-chloroplasts',
    explanation: tx('A typical green leaf cell has a cell wall for support, a membrane controlling exchange, cytoplasm, a nucleus, mitochondria, ribosomes, a large vacuole containing cell sap and chloroplasts carrying out photosynthesis. The wall is outside the membrane; they are not the same structure. Plant cells respire as well as photosynthesise. Not all plant cells have chloroplasts: many root cells do not receive light. Approved images of different plant parts help us see that plants are made of cells while their structures vary. A labelled model represents studied structures, not their true colours or exact proportions.', 'Une cellule typique de feuille verte possède une paroi de soutien, une membrane contrôlant les échanges, du cytoplasme, un noyau, des mitochondries, des ribosomes, une grande vacuole contenant du suc cellulaire et des chloroplastes réalisant la photosynthèse. La paroi est extérieure à la membrane ; ce ne sont pas la même structure. Les cellules végétales respirent aussi. Toutes n’ont pas de chloroplastes : beaucoup de cellules de racine ne reçoivent pas de lumière. Des images approuvées de différentes parties montrent que les plantes sont constituées de cellules dont les structures varient. Le modèle n’en représente ni les vraies couleurs ni les proportions exactes.'),
    example: tx('Compare an approved leaf-cell image and an onion-bulb epidermis image. Label the structures actually visible, then use a key for schematic organelles added to your drawing. Explain why a bulb image without visible chloroplasts does not mean it is an animal cell. Make separate wall and membrane outlines in your paper model.', 'Compare une image approuvée de cellule de feuille et une d’épiderme de bulbe d’oignon. Légende ce qui est visible, puis distingue par une clé les organites schématiques ajoutés. L’absence de chloroplastes visibles dans le bulbe n’en fait pas une cellule animale. Trace séparément paroi et membrane dans ton modèle en papier.'),
    question: tx('Which plant-cell structure carries out photosynthesis in a green leaf?', 'Quelle structure réalise la photosynthèse dans une cellule de feuille verte ?'),
    options: { en: ['Chloroplast', 'Cell wall alone', 'Vacuole alone'], fr: ['Le chloroplaste', 'La paroi seule', 'La vacuole seule'] },
    correction: tx('Link function to structure. Chloroplasts contain the machinery for photosynthesis. The wall supports the cell and the vacuole contains cell sap; those functions are different. Locate all three in the model and retry.', 'Relie chaque fonction à sa structure. Les chloroplastes réalisent la photosynthèse. La paroi soutient la cellule et la vacuole contient le suc cellulaire. Repère les trois dans le modèle et réessaie.'),
    tasks: [tx('Using approved pictures/video from two plant parts, independently identify structures, explain the studied organelles, draw and label a plant cell and build a safe paper/card model. Distinguish membrane/wall and explain why chloroplasts need not occur in every plant cell. Your teacher inspects the real work.', 'Avec des images ou une vidéo approuvées de deux parties végétales, identifie seul les structures, explique les organites étudiés, dessine une cellule légendée et construis un modèle sûr. Distingue membrane/paroi et explique la présence variable de chloroplastes. L’enseignant examine le vrai travail.'), tx('Explain wall, membrane, cytoplasm, nucleus, vacuole, chloroplast, mitochondrion and ribosome functions using your own labelled model and a checked plant-cell image. Record which structures are schematic rather than directly visible and discuss with your teacher.', 'Explique les fonctions de paroi, membrane, cytoplasme, noyau, vacuole, chloroplaste, mitochondrie et ribosome avec ton modèle personnel et une image vérifiée. Indique ce qui est schématique plutôt que visible et discute avec l’enseignant.')],
    transfer: [tx('A learner labels a root cell “animal” because it lacks chloroplasts. Use teacher-approved evidence and a new annotated diagram to explain the mistake and identify useful distinguishing structures.', 'Un élève appelle une cellule de racine « animale » faute de chloroplastes. Avec des preuves approuvées et un nouveau schéma annoté, explique l’erreur et repère les structures utiles.'), tx('Compare your plant and animal models. Explain shared respiration-related structures and plant-specific features, noting that one simplified drawing does not represent every specialised cell.', 'Compare tes modèles végétal et animal. Explique les structures communes liées à la respiration et les caractéristiques végétales, sans généraliser un dessin simplifié à toutes les cellules spécialisées.')],
    retention: [tx('How are a plant cell wall and membrane related?', 'Quelle relation existe entre paroi et membrane végétales ?'), tx('Do all plant cells necessarily contain chloroplasts?', 'Toutes les cellules végétales contiennent-elles nécessairement des chloroplastes ?')],
    retentionOptions: [{ en: ['The wall is outside the membrane', 'They are the same structure', 'The membrane replaces the nucleus'], fr: ['La paroi est extérieure à la membrane', 'Ce sont la même structure', 'La membrane remplace le noyau'] }, { en: ['No; many root cells do not', 'Yes; all root cells photosynthesise', 'No plant cell has chloroplasts'], fr: ['Non ; beaucoup de cellules de racine n’en ont pas', 'Oui ; toutes les cellules de racine réalisent la photosynthèse', 'Aucune cellule végétale n’en possède'] }],
    criteria: [tx('Inspect actual source observations, labelled drawing/model and independent organelle-function explanations.', 'Examiner observations documentées, dessin/modèle réels et explications autonomes des fonctions.'), tx('Check membrane/wall distinction, shared respiration structures and variable chloroplast distribution without invented observations.', 'Vérifier membrane/paroi, structures de respiration communes et répartition variable des chloroplastes, sans observations inventées.')],
  }),
];

B7_SCIENCE_FOUNDATIONS.push(
  unit(44, 1, {
    title: tx('Water moves through a repeating cycle', 'Le cycle répété de l’eau'),
    subskills: ['identify-water-sources-and-processes', 'link-water-cycle-stages', 'explain-repetition-with-a-source'], misconception: 'confuses-evaporation-and-condensation',
    explanation: tx('Water moves among the sea, rivers, lakes, soil, living things and the atmosphere. Evaporation changes liquid water into water vapour; transpiration releases water vapour from plants. Cooling vapour can condense into tiny droplets, forming clouds. Precipitation returns water as rain or other forms; water collects, flows as runoff or enters soil. Solar energy drives much evaporation and gravity helps return and move water. The cycle has linked pathways, not one compulsory starting point. Clouds are droplets or ice crystals, not simply invisible water vapour. Repetition describes ongoing movement, not a promise that the same place receives rain every day.', 'L’eau circule entre mer, cours d’eau, lacs, sol, êtres vivants et atmosphère. L’évaporation transforme l’eau liquide en vapeur ; la transpiration végétale libère de la vapeur. En refroidissant, la vapeur peut se condenser en fines gouttelettes formant des nuages. Les précipitations ramènent l’eau ; elle s’accumule, ruisselle ou pénètre le sol. L’énergie solaire favorise l’évaporation et la gravité aide au retour et au déplacement. Le cycle comporte plusieurs chemins, sans début obligatoire. Les nuages contiennent des gouttelettes ou cristaux, pas seulement de la vapeur invisible. La répétition n’implique pas de pluie quotidienne au même endroit.'),
    example: tx('Draw arrows from Lake Volta to the atmosphere labelled evaporation, from vapour to cloud droplets labelled condensation and from clouds to land labelled precipitation. Add plants → atmosphere for transpiration and soil/river → lake for return flow. Trace a second possible pathway through soil. Explain why your diagram loops rather than ending at rainfall.', 'Dessine des flèches du lac Volta vers l’atmosphère pour l’évaporation, de la vapeur aux gouttelettes pour la condensation et des nuages vers le sol pour les précipitations. Ajoute plantes → atmosphère pour la transpiration et sol/rivière → lac pour le retour. Trace un second trajet passant par le sol. Explique pourquoi le dessin ne s’arrête pas à la pluie.'),
    question: tx('Which process changes water vapour into liquid droplets?', 'Quel processus transforme la vapeur d’eau en gouttelettes liquides ?'),
    options: { en: ['Condensation', 'Evaporation', 'Transpiration alone'], fr: ['La condensation', 'L’évaporation', 'La transpiration seule'] },
    correction: tx('Check the direction of the change. Liquid → vapour is evaporation; vapour → droplets is condensation. Transpiration releases vapour from plants. Label the starting and ending states on the arrow, then retry.', 'Vérifie le sens du changement. Liquide → vapeur : évaporation ; vapeur → gouttelettes : condensation. La transpiration libère de la vapeur des plantes. Note l’état initial et final sur la flèche, puis réessaie.'),
    tasks: [tx('Study an approved picture/video and a checked book, article or other permitted source. Independently draw a water-cycle flow diagram including evaporation, condensation, precipitation and transpiration, natural water sources and return pathways. Cite the source and explain why the pattern repeats. Show the actual diagram to your teacher.', 'Étudie une image/vidéo approuvée et un livre, article ou autre source autorisée vérifiée. Dessine seul un cycle avec évaporation, condensation, précipitations, transpiration, sources naturelles et voies de retour. Cite la source et explique la répétition. Montre le vrai schéma à l’enseignant.'), tx('From a different approved water-cycle picture, independently explain the linked processes and draw two possible water pathways, including plant transpiration. Use a checked information source to justify repetition and distinguish the diagram from a daily local forecast.', 'Avec une autre image approuvée, explique seul les processus et dessine deux trajets possibles incluant la transpiration végétale. Appuie la répétition sur une source vérifiée et distingue schéma général et prévision locale quotidienne.')],
    transfer: [tx('Explain what happens to water after rain on a school roof, using a labelled pathway through collection/runoff, evaporation and possible precipitation. Identify where your explanation is a model rather than an actual observation and justify each change.', 'Explique le trajet de l’eau après une pluie sur un toit scolaire, avec collecte/ruissellement, évaporation et précipitations possibles. Distingue modèle et observation réelle et justifie les changements.'), tx('A classmate ends a cycle at rainfall and omits plants. Independently revise the diagram to restore linked return pathways and transpiration. Cite a checked source and explain why no single starting point is necessary.', 'Un camarade termine le cycle à la pluie et oublie les plantes. Corrige seul les voies de retour et ajoute la transpiration. Cite une source vérifiée et explique pourquoi aucun départ unique n’est obligatoire.')],
    retention: [tx('What is water-vapour release from plants called?', 'Comment appelle-t-on la libération de vapeur d’eau par les plantes ?'), tx('Why does a water-cycle diagram have return arrows?', 'Pourquoi le schéma du cycle de l’eau comporte-t-il des flèches de retour ?')],
    retentionOptions: [{ en: ['Transpiration', 'Only precipitation', 'Freezing every leaf'], fr: ['La transpiration', 'Uniquement les précipitations', 'Le gel de chaque feuille'] }, { en: ['Water can circulate through linked pathways repeatedly', 'Water stops moving after rain', 'Every place has rain daily'], fr: ['L’eau peut circuler à nouveau par des voies liées', 'L’eau s’arrête après la pluie', 'Il pleut chaque jour partout'] }],
    criteria: [tx('Inspect an actual independent diagram with correct change directions, plant pathway, natural sources and return links.', 'Examiner le vrai schéma autonome : sens des changements, trajet végétal, sources naturelles et retours.'), tx('Check the cited information source and reasoned explanation of repetition; no invented search or local observation.', 'Vérifier la source citée et l’explication raisonnée de la répétition ; aucune recherche ou observation locale inventée.')],
  }),
  unit(45, 1, {
    title: tx('Why the water cycle matters', 'L’importance du cycle de l’eau'),
    subskills: ['link-water-cycle-to-community', 'explain-energy-nutrients-groundwater-weather', 'distinguish-renewal-from-drinking-safety'], misconception: 'assumes-rainwater-is-automatically-safe-to-drink',
    explanation: tx('The water cycle redistributes water needed by people, plants and animals. Water entering soil can recharge groundwater and raise the water table under suitable conditions; runoff can carry dissolved nutrients, but also pollutants. Evaporation absorbs energy and condensation releases energy into the surroundings, helping move heat. Clouds and precipitation are part of weather patterns. Evaporation can leave many dissolved substances behind, but rain and collected water can become contaminated: the cycle does not guarantee drinking safety. Do not taste collected water. Community benefits depend on rainfall, soil, vegetation, storage and management; one diagram cannot predict them exactly.', 'Le cycle redistribue l’eau nécessaire aux humains, plantes et animaux. L’infiltration peut recharger les eaux souterraines et relever la nappe selon les conditions ; le ruissellement transporte des nutriments dissous, mais aussi des polluants. L’évaporation absorbe de l’énergie et la condensation en libère dans le milieu, contribuant au transfert de chaleur. Nuages et précipitations participent au temps météorologique. L’évaporation laisse derrière elle beaucoup de substances dissoutes, mais pluie et eau collectée peuvent être contaminées : le cycle ne garantit pas la potabilité. Ne goûte pas l’eau collectée. Les effets dépendent des pluies, du sol, de la végétation, du stockage et de la gestion.'),
    example: tx('Draw rain over a Ghanaian school garden. One arrow enters soil and may recharge groundwater; another flows across the surface carrying dissolved nutrients or pollutants. Add evaporation absorbing energy and condensation releasing it. Label uses for crops and people, but mark collected water “not proven safe to drink”. Explain each link instead of claiming rainfall creates new energy.', 'Dessine la pluie sur un jardin scolaire ghanéen. Une flèche pénètre le sol et peut recharger la nappe ; une autre transporte en surface nutriments dissous ou polluants. Ajoute l’énergie absorbée par évaporation et libérée par condensation. Indique les usages, en marquant l’eau collectée « potabilité non établie ». Explique les liens sans prétendre que la pluie crée de l’énergie.'),
    question: tx('Which statement about rain and the water cycle is justified?', 'Quelle affirmation sur la pluie et le cycle de l’eau est justifiée ?'),
    options: { en: ['Rain can replenish water, but drinking safety still needs checking', 'All collected rain is automatically safe to drink', 'The cycle creates unlimited new energy'], fr: ['La pluie peut renouveler l’eau, mais sa potabilité doit être vérifiée', 'Toute pluie collectée est automatiquement potable', 'Le cycle crée une énergie nouvelle illimitée'] },
    correction: tx('Separate water movement from safety and energy creation. Rain can replenish sources; contamination may still occur. Condensation releases energy previously transferred through the cycle, rather than creating energy. Revise the claim and retry.', 'Distingue circulation, sécurité et création d’énergie. La pluie peut renouveler des réserves, mais une contamination reste possible. La condensation libère de l’énergie transférée, sans en créer. Corrige l’affirmation, puis réessaie.'),
    tasks: [tx('Independently annotate a community water-cycle diagram explaining energy transfer, nutrient transport, groundwater/water table, weather and water renewal. Use an approved picture/video to describe the stages. Explain the limits of the phrase “clean water” and why drinking safety cannot be inferred. Teacher review is required.', 'Annote seul un cycle dans une communauté : transferts d’énergie, nutriments, eaux souterraines/nappe, météo et renouvellement. Décris les étapes avec une image/vidéo approuvée. Explique les limites de « eau propre » et l’absence de preuve de potabilité. Examen requis.'), tx('Prepare your own diagram and explanation of how water cycling supports a school/community. Cover the five source themes: energy release, nutrients, water table, weather and clean-water renewal, distinguishing benefits from contamination risks. Present and justify your work to your teacher.', 'Prépare ton schéma et explique le rôle du cycle pour une école/communauté. Traite les cinq thèmes de la source : énergie libérée, nutriments, nappe, météo et renouvellement d’eau propre, sans ignorer les contaminations. Présente et justifie le travail à l’enseignant.')],
    transfer: [tx('A fictional school removes vegetation near a water source. Use a new diagram to explain possible changes in runoff, infiltration and nutrient movement, clearly marking assumptions and explaining why the diagram alone cannot prove water quality.', 'Une école fictive retire la végétation près d’une réserve. Avec un nouveau schéma, explique les changements possibles de ruissellement, infiltration et transport des nutriments. Indique les hypothèses et pourquoi le schéma ne prouve pas la qualité de l’eau.'), tx('Evaluate a poster claiming “Rain creates energy and all rainwater is safe”. Independently replace it with an accurate community diagram and explanations of energy transfer, groundwater and water-safety limits.', 'Évalue une affiche disant « La pluie crée de l’énergie et toute pluie est potable ». Remplace-la par un schéma communautaire exact et explique transferts d’énergie, nappe et limites de potabilité.')],
    retention: [tx('What can infiltration help replenish?', 'Que peut contribuer à renouveler l’infiltration ?'), tx('What happens to energy during condensation?', 'Que devient l’énergie lors de la condensation ?')],
    retentionOptions: [{ en: ['Groundwater under suitable conditions', 'An unlimited fuel supply', 'Only the colour of rain'], fr: ['Les eaux souterraines selon les conditions', 'Une réserve illimitée de carburant', 'Seulement la couleur de la pluie'] }, { en: ['Energy is released to the surroundings', 'New energy is created from nothing', 'Energy transfer is impossible'], fr: ['De l’énergie est libérée dans le milieu', 'Une énergie nouvelle apparaît à partir de rien', 'Tout transfert d’énergie est impossible'] }],
    criteria: [tx('Inspect the actual community diagram and explanations across all five source themes with correct energy transfer.', 'Examiner le vrai schéma communautaire et les cinq thèmes de la source avec des transferts d’énergie exacts.'), tx('Require independent causal reasoning, stated assumptions and no unsupported claim of drinking safety.', 'Exiger un raisonnement causal autonome, des hypothèses explicites et aucune potabilité affirmée sans preuve.')],
  }),
  unit(46, 1, {
    title: tx('The housefly life cycle', 'Le cycle de la mouche domestique'),
    subskills: ['identify-housefly-stages', 'sequence-and-link-life-cycle', 'annotate-stage-changes'], misconception: 'omits-pupa-or-reverses-larva-and-pupa',
    explanation: tx('A housefly develops through egg → larva (maggot) → pupa → adult. Larvae feed and grow; the pupa is a stage of internal change before an adult emerges. Adults reproduce and females lay eggs, completing the cycle. An egg does not grow directly into a winged adult. Use teacher-approved pictures or your own paper cards to represent stages. Arrows show development and reproduction, not a single fly becoming its own egg. Timing varies with conditions, so do not invent a fixed number of days. No breeding, touching waste or collecting live flies is needed for this activity.', 'La mouche domestique passe par œuf → larve (asticot) → pupe → adulte. La larve se nourrit et grandit ; la pupe est une phase de transformation interne avant la sortie de l’adulte. Les adultes se reproduisent et les femelles pondent, ce qui ferme le cycle. Un œuf ne devient pas directement un adulte ailé. Utilise des images approuvées ou des cartes en papier. Les flèches indiquent développement et reproduction, pas un adulte redevenant son propre œuf. La durée varie selon les conditions : n’invente pas un nombre fixe de jours. Aucun élevage, contact avec des déchets ou prélèvement de mouches n’est nécessaire.'),
    example: tx('Make four cards labelled egg, larva, pupa and adult, add a simple drawing to each and arrange them in a loop. Write one stage note per card: egg hatches; larva grows; pupa transforms; adult reproduces. Explain the adult → eggs arrow as reproduction and check your sequence against an approved image.', 'Fabrique quatre cartes œuf, larve, pupe et adulte avec un dessin simple et range-les en boucle. Note : l’œuf éclot ; la larve grandit ; la pupe se transforme ; l’adulte se reproduit. Explique la flèche adulte → œufs et vérifie avec une image approuvée.'),
    question: tx('Which stage comes between the feeding larva and the adult housefly?', 'Quelle étape se trouve entre la larve nourricière et la mouche adulte ?'),
    options: { en: ['Pupa', 'Egg again without reproduction', 'A seed'], fr: ['La pupe', 'Un nouvel œuf sans reproduction', 'Une graine'] },
    correction: tx('Lay out all four cards. Egg hatches to larva; larva develops into pupa; adult emerges from pupa. The pupal stage must not be skipped. Explain the change represented by each arrow and retry.', 'Dispose les quatre cartes. L’œuf donne une larve, la larve devient pupe et l’adulte sort de la pupe. Ne saute pas cette étape. Explique chaque flèche, puis réessaie.'),
    tasks: [tx('Independently arrange real paper cards/cut-outs for egg, larva, pupa and adult, draw each stage in a linked cycle and write a note explaining each stage. Explain the reproduction arrow to your teacher, who must inspect the actual arrangement and drawing.', 'Range seul de vraies cartes/découpages œuf, larve, pupe et adulte, dessine le cycle lié et écris une note par étape. Explique la flèche de reproduction à l’enseignant ; il doit voir la vraie disposition et le dessin.'), tx('Using a different approved picture set, identify each housefly stage, make an independent labelled cycle and describe development and reproduction in your own words. Show the stage notes and cards; do not substitute live breeding.', 'Avec un autre jeu d’images approuvé, identifie les étapes, dessine seul le cycle légendé et décris développement et reproduction avec tes mots. Présente notes et cartes ; aucun élevage de mouches.')],
    transfer: [tx('Correct a fictional diagram showing egg → adult → larva. Independently rebuild all four stages, add developmental and reproduction arrows and explain why the original order fails.', 'Corrige un schéma fictif œuf → adulte → larve. Reconstruis seul les quatre étapes, ajoute les flèches et explique pourquoi l’ordre initial est faux.'), tx('Design a classroom card puzzle that distinguishes the housefly larva from its pupa. Provide a correct cycle and explanatory answer key, and let your teacher inspect the actual puzzle.', 'Conçois un puzzle de cartes distinguant larve et pupe. Fournis le cycle correct et une clé expliquée, puis montre le vrai puzzle à l’enseignant.')],
    retention: [tx('What is the correct housefly developmental order?', 'Quel est l’ordre correct du développement de la mouche domestique ?'), tx('What does the adult-to-egg arrow represent?', 'Que représente la flèche adulte-vers-œufs ?')],
    retentionOptions: [{ en: ['Egg → larva → pupa → adult', 'Egg → adult → larva → pupa', 'Pupa → egg → larva → seed'], fr: ['Œuf → larve → pupe → adulte', 'Œuf → adulte → larve → pupe', 'Pupe → œuf → larve → graine'] }, { en: ['Reproduction producing new eggs', 'The same adult shrinking into its own egg', 'A stage with no biological meaning'], fr: ['La reproduction donnant de nouveaux œufs', 'Le même adulte rétrécissant en son propre œuf', 'Une étape sans signification biologique'] }],
    criteria: [tx('Inspect independently arranged cards, all four drawn stages, linked arrows and meaningful stage notes.', 'Examiner les cartes rangées seul, les quatre étapes dessinées, les flèches et les notes pertinentes.'), tx('Check development versus reproduction and distinguish larva/pupa without unsafe live collection or invented timings.', 'Vérifier développement/reproduction et larve/pupe, sans collecte dangereuse ni durées inventées.')],
  }),
  unit(47, 1, {
    title: tx('Interrupting the housefly contamination pathway', 'Interrompre la contamination par les mouches'),
    subskills: ['explain-housefly-feeding-and-contamination', 'design-a-relevant-intervention', 'communicate-an-evidence-based-message'], misconception: 'assumes-a-fly-creates-disease-without-contamination',
    explanation: tx('Houseflies feed around decaying food, animal remains, manure and other waste. Microorganisms from contaminated places can be carried to food or surfaces, contributing to illnesses such as dysentery and food poisoning. Flies are also a nuisance. A useful intervention interrupts a pathway: cover food, keep waste in closed containers and arrange appropriate waste disposal, or maintain screens where suitable. A poster alone does not prove an intervention was used or reduced disease. Use drawings and approved information, not handling waste, breeding flies or testing food. Design a feasible action and explain it to an approved audience with adult permission.', 'Les mouches fréquentent aliments en décomposition, restes animaux, fumier et déchets. Des micro-organismes peuvent être transportés de ces lieux vers aliments ou surfaces, contribuant à des maladies comme la dysenterie et les intoxications alimentaires. Les mouches sont aussi une nuisance. Une intervention utile coupe un trajet : couvrir les aliments, fermer les récipients à déchets, organiser leur évacuation ou entretenir des moustiquaires adaptées. Une affiche seule ne prouve ni mise en œuvre ni baisse des maladies. Utilise dessins et informations approuvées, sans manipuler de déchets, élever des mouches ou tester des aliments. Conçois une action réalisable et explique-la à un public autorisé avec permission adulte.'),
    example: tx('Draw waste → fly → uncovered food → possible exposure. Place a food cover across the fly-to-food arrow and a closed bin at the waste source. Explain what each action changes. Tell a class audience how to keep the cover in use; do not claim a measured reduction in illness unless genuine evidence exists.', 'Dessine déchets → mouche → aliment découvert → exposition possible. Place une protection sur la flèche vers l’aliment et une poubelle fermée au départ. Explique leurs rôles. Présente à la classe comment garder la protection en place ; ne prétends pas avoir mesuré une baisse des maladies sans vraie preuve.'),
    question: tx('Which action directly interrupts flies reaching prepared food?', 'Quelle action empêche directement les mouches d’atteindre un aliment préparé ?'),
    options: { en: ['Keep food appropriately covered', 'Leave food uncovered to attract more flies', 'Handle waste and then touch food without cleaning'], fr: ['Garder les aliments correctement couverts', 'Laisser les aliments découverts pour attirer les mouches', 'Toucher les déchets puis les aliments sans nettoyage'] },
    correction: tx('Trace where contamination can travel. A suitable food cover blocks the fly-to-food link; attracting flies or transferring contamination by hands does not. Choose an action tied to the pathway, explain why it helps and retry.', 'Suis le trajet de contamination. Une protection adaptée coupe le lien mouche-aliment ; attirer les mouches ou transférer les salissures par les mains ne le coupe pas. Relie l’action au trajet, justifie-la et réessaie.'),
    tasks: [tx('Independently draw the feeding/contamination pathway, explain disease transfer, food poisoning and nuisance, and design a feasible intervention. Make a clear illustrated message and deliver it to a teacher-approved class/community audience. Your teacher must inspect the design and observe the actual communication; record honestly any action not completed.', 'Dessine seul le trajet alimentation-contamination, explique transmission, intoxication et nuisance, puis conçois une intervention réalisable. Prépare un message illustré et présente-le à un public autorisé. L’enseignant voit le projet et observe la vraie communication ; indique honnêtement ce qui reste inachevé.'), tx('Create an independent cartoon explaining how a fly moves from waste to food and how a different appropriate intervention interrupts that link. Explain limitations and present the message to an approved audience while your teacher observes.', 'Crée seul une bande dessinée montrant le trajet déchets-aliments et une autre intervention adaptée. Explique les limites et présente le message à un public autorisé sous observation de l’enseignant.')],
    transfer: [tx('For a fictional school canteen with exposed bins and food, independently compare two interventions, identify which links each interrupts and design a practical maintenance message. Do not invent disease statistics or an implemented action.', 'Pour une cantine fictive aux poubelles et aliments ouverts, compare seul deux interventions, repère les liens coupés et conçois un message d’entretien réalisable. N’invente ni statistiques ni action réalisée.'), tx('Review a new anti-fly poster that blames all illness on flies and gives no action. Replace it with an accurate pathway, a feasible intervention and a short observed explanation to an approved audience.', 'Évalue une affiche imputant toute maladie aux mouches sans proposer d’action. Remplace-la par un trajet exact, une intervention réalisable et une courte explication observée devant un public autorisé.')],
    retention: [tx('How can a housefly contribute to food contamination?', 'Comment une mouche peut-elle contribuer à contaminer un aliment ?'), tx('What evidence supports a claim that a learner educated an audience?', 'Quelle preuve étaye l’affirmation qu’un élève a informé un public ?')],
    retentionOptions: [{ en: ['By carrying microorganisms from contaminated places', 'By turning every food into poison instantly', 'Only by its colour'], fr: ['En transportant des micro-organismes de lieux contaminés', 'En transformant immédiatement tout aliment en poison', 'Seulement par sa couleur'] }, { en: ['An actual observed communication with its content', 'An imagined audience written as completed', 'An option selection alone'], fr: ['Une vraie communication observée avec son contenu', 'Un public imaginaire présenté comme réel', 'Un choix de réponse seul'] }],
    criteria: [tx('Check accurate feeding/pathway drawings and causal links to disease transfer, food poisoning and nuisance.', 'Vérifier dessins et liens exacts entre alimentation, contamination, transmission, intoxication et nuisance.'), tx('Inspect the actual intervention design and observed audience communication; reject invented implementation or outcome claims.', 'Examiner le vrai projet et la communication observée ; refuser mises en œuvre ou résultats inventés.')],
  }),
);

B7_SCIENCE_FOUNDATIONS.push(
  unit(48, 1, {
    title: tx('Finding and comparing plant nutrient sources', 'Repérer et comparer les sources de nutriments végétaux'),
    subskills: ['record-community-nutrient-sources', 'compare-organic-and-inorganic-sources', 'compare-documented-volumes'], misconception: 'treats-equal-volumes-as-equal-nutrient-content',
    explanation: tx('Plants need nutrients. In this farming context, organic nutrient sources include compost and suitably managed manure derived from living material; inorganic sources include mineral fertilisers. “Organic” here is a source category, not a claim that every sample is harmless or certified organic farming. Record the actual sources available in a defined community survey, their evidence and any uncertainties. Organic and inorganic materials differ in nutrient concentration and release, so the same volume does not necessarily provide the same nutrients. Required amounts depend on crop, soil, product and verified guidance. Never invent a universal dose or an observation, and do not handle unknown fertiliser or raw manure.', 'Les plantes ont besoin de nutriments. Dans ce contexte agricole, les sources organiques comprennent compost et fumier correctement géré issus du vivant ; les sources minérales comprennent des engrais minéraux. « Organique » désigne ici l’origine, pas une innocuité ou une certification biologique. Note les sources réellement disponibles dans un périmètre d’enquête défini, avec preuves et incertitudes. Leur concentration et libération varient : un même volume n’apporte pas forcément les mêmes nutriments. Les quantités dépendent de la culture, du sol, du produit et de recommandations vérifiées. N’invente ni dose universelle ni observation et ne manipule pas d’engrais inconnu ou de fumier brut.'),
    example: tx('Create columns: source, observed evidence, organic/inorganic category, plant/crop, recommended amount and unit, guidance source. A school compost pile can be recorded only if genuinely observed or documented. For comparison, use teacher-provided verified recommendations for specified crops; preserve the units and explain why one litre of compost cannot automatically replace one litre of mineral fertiliser. Mark missing data “not verified”.', 'Crée les colonnes source, preuve observée, catégorie, plante/culture, quantité recommandée et unité, référence. Ne note un compost scolaire que s’il est réellement observé ou documenté. Compare des recommandations vérifiées fournies par l’enseignant pour des cultures précises ; conserve les unités et explique pourquoi un litre de compost ne remplace pas automatiquement un litre d’engrais minéral. Note « non vérifié » si nécessaire.'),
    question: tx('Can equal volumes of compost and mineral fertiliser automatically be treated as equal nutrient doses?', 'Peut-on considérer automatiquement des volumes égaux de compost et d’engrais minéral comme des doses nutritives égales ?'),
    options: { en: ['No; concentration and appropriate crop guidance must be checked', 'Yes; volume alone proves equivalence', 'Yes; every plant needs the same amount'], fr: ['Non ; concentration et recommandations adaptées doivent être vérifiées', 'Oui ; le volume suffit à prouver l’équivalence', 'Oui ; toutes les plantes demandent la même quantité'] },
    correction: tx('Volume measures space, not the nutrient content by itself. Identify the product, crop and verified recommendation before comparing amounts. Do not turn a comparison into an application dose without evidence. Explain what information is missing and retry.', 'Le volume mesure l’espace occupé, pas à lui seul les nutriments. Identifie produit, culture et recommandation vérifiée avant de comparer. Ne transforme pas une comparaison en dose d’application sans preuve. Explique les informations manquantes, puis réessaie.'),
    tasks: [tx('With permission and adult supervision, survey a defined safe community area or its genuine documented records. List all nutrient sources found within that scope and classify them in an organic/inorganic comparison table. Compare verified recommended volumes/amounts for different specified plants, retaining units and sources. Your teacher checks actual evidence, scope and calculations; missing guidance stays unfinished.', 'Avec permission et supervision, enquête dans une zone sûre définie ou sur ses vrais documents. Liste toutes les sources repérées dans ce périmètre et classe-les dans un tableau organique/minéral. Compare des quantités/volumes recommandés vérifiés pour des plantes précises, avec unités et références. L’enseignant vérifie preuves, périmètre et calculs ; sans recommandation, le travail reste inachevé.'), tx('Independently explain a second set of genuinely observed/documented nutrient sources, distinguishing source categories and physical volume from nutrient concentration. Use checked guidance to compare amounts for two crops; show the original evidence and your comparison to your teacher.', 'Explique seul un autre ensemble de sources réellement observées/documentées, en distinguant origine, volume et concentration. Compare les quantités de deux cultures avec des recommandations vérifiées ; présente les documents et ta comparaison à l’enseignant.')],
    transfer: [tx('A fictional gardener substitutes equal buckets of two different nutrient materials. Explain why this is not justified, specify the product/crop information needed and use supplied verified recommendations to produce a corrected comparison, not an invented dose.', 'Un jardinier fictif échange des seaux égaux de deux matières nutritives. Explique pourquoi cela ne suffit pas, précise les informations nécessaires et utilise les recommandations vérifiées fournies pour corriger la comparaison sans inventer de dose.'), tx('Prepare a new community inventory plan that distinguishes observed, reported and unverified sources. Explain how you would compare crop-specific recommended volumes without claiming to have conducted an unperformed survey.', 'Prépare un nouveau plan d’inventaire distinguant sources observées, rapportées et non vérifiées. Explique la comparaison de volumes recommandés selon les cultures sans prétendre avoir mené une enquête non réalisée.')],
    retention: [tx('Which is an organic nutrient source in this lesson’s farming classification?', 'Quelle source est organique dans la classification agricole de cette leçon ?'), tx('What should you record when an application recommendation is missing?', 'Que faut-il noter lorsqu’une recommandation d’application manque ?')],
    retentionOptions: [{ en: ['Suitably prepared compost', 'Every manufactured mineral fertiliser', 'The empty container alone'], fr: ['Un compost correctement préparé', 'Tout engrais minéral fabriqué', 'Le récipient vide seul'] }, { en: ['Not verified; obtain appropriate guidance before application', 'Invent a convenient dose', 'Assume all crops require equal volumes'], fr: ['Non vérifié ; obtenir les recommandations adaptées avant application', 'Inventer une dose pratique', 'Supposer des volumes égaux pour toutes les cultures'] }],
    criteria: [tx('Inspect the genuine scoped inventory and source-category comparison; distinguish observation from report and uncertainty.', 'Examiner le vrai inventaire délimité et les catégories ; distinguer observation, témoignage et incertitude.'), tx('Check documented crop-specific volume/amount comparisons, units and guidance; no fabricated universal dose or unobserved survey.', 'Vérifier comparaisons documentées, unités et recommandations selon les cultures ; aucune dose universelle ni enquête fictive.')],
  }),
  unit(48, 2, {
    title: tx('Plant nutrient materials: appearance and supervised application', 'Matières nutritives : aspect et application supervisée'),
    subskills: ['describe-material-properties', 'explain-application-choice', 'perform-supervised-application'], misconception: 'counts-a-paper-plan-as-completed-field-application',
    explanation: tx('Nutrient materials may be crumbly organic matter, granules, powders or liquids. Physical form affects measuring, spreading, dissolving and placement, but appearance alone cannot establish contents, safety or a correct dose. Compost may be incorporated into suitable soil under guidance; a specified mineral fertiliser must follow its verified product/crop instructions. Discuss how each approved material will be used before any field activity. A teacher must select permitted materials, check instructions and supervise real application in a school garden or approved field. No tasting, guessing, unsupervised mixing or handling raw manure. A drawing can explain a method but cannot prove that you performed it.', 'Les matières nutritives peuvent être friables, granulées, poudreuses ou liquides. Leur forme influence mesure, répartition, dissolution et placement, sans prouver composition, sécurité ou dose. Un compost peut être incorporé au sol selon des recommandations adaptées ; un engrais minéral précis suit ses consignes vérifiées de produit/culture. Discute de chaque matière autorisée avant l’activité. L’enseignant choisit les produits permis, vérifie les instructions et supervise la vraie application au jardin scolaire ou sur un terrain autorisé. Aucun goûtage, dosage deviné, mélange autonome ou contact avec du fumier brut. Un dessin explique une méthode sans prouver sa réalisation.'),
    example: tx('Compare approved pictures or sealed labels of compost and a granular fertiliser. Record visible structure and the verified instruction source, then discuss handling and placement with your group. Before a real demonstration, the teacher confirms the crop, material, measured amount and precautions. Record what was actually applied and who observed it; if only a model was used, label it “model, practical still pending”.', 'Compare des images approuvées ou étiquettes fermées de compost et d’engrais granulaire. Note l’aspect et la source des consignes, puis discute manipulation et placement en groupe. Avant la démonstration réelle, l’enseignant confirme culture, matière, quantité mesurée et précautions. Note l’action réellement faite et l’observateur ; si seul un modèle est utilisé, indique « modèle, pratique en attente ».'),
    question: tx('Which evidence demonstrates practical application rather than only planning it?', 'Quelle preuve démontre l’application pratique plutôt que sa seule préparation ?'),
    options: { en: ['Teacher observation of the learner’s actual permitted field application', 'A guessed dose typed into a text box', 'A drawing falsely labelled as completed application'], fr: ['L’observation par l’enseignant d’une vraie application autorisée', 'Une dose devinée saisie dans une zone de texte', 'Un dessin faussement présenté comme une application réalisée'] },
    correction: tx('Separate preparation from performance. Pictures and a plan help you explain, but the practical needs real permitted application observed by a teacher. If equipment or approval is missing, keep it pending instead of claiming completion. Retry using that distinction.', 'Distingue préparation et réalisation. Images et plan aident à expliquer, mais la pratique exige une vraie application autorisée observée. Si matériel ou autorisation manque, garde la tâche en attente. Réessaie avec cette distinction.'),
    tasks: [tx('Describe the actual physical properties of teacher-approved organic and inorganic nutrient sources, discuss their field methods in a group and independently explain your choices. Under qualified adult supervision, demonstrate permitted application of each type using verified instructions in an approved garden. Your teacher must directly observe and record the real work; if a type cannot safely be performed, leave its practical evidence pending.', 'Décris les propriétés réelles de sources organiques et minérales approuvées, discute en groupe des méthodes et justifie seul tes choix. Sous supervision qualifiée, réalise l’application autorisée de chaque type selon des consignes vérifiées dans un jardin approuvé. L’enseignant observe et note le vrai travail ; tout type non réalisable sans danger reste en attente.'), tx('For a different teacher-approved crop/material pair, explain how form affects measurement and application, cite the checked instructions and carry out the authorised operation under direct supervision. Compare with the other nutrient-source type. Submit notes and obtain genuine teacher observation, not a self-certified claim.', 'Pour une autre association culture/matière approuvée, explique le lien entre forme, mesure et application, cite les consignes et réalise l’opération autorisée sous observation directe. Compare avec l’autre type de source. Présente les notes et une vraie observation de l’enseignant, pas une auto-certification.')],
    transfer: [tx('A new nutrient material has an unreadable label. Explain why appearance does not justify a dose or application, identify what must be verified and prepare a conditional plan. Actual application remains pending until the teacher obtains suitable guidance and observes it.', 'Une nouvelle matière a une étiquette illisible. Explique pourquoi son aspect ne justifie ni dose ni application, précise les vérifications et prépare un plan conditionnel. La pratique reste en attente jusqu’aux consignes adaptées et à l’observation de l’enseignant.'), tx('In another approved garden setting, independently adapt an application plan to documented crop/material instructions and explain the changed physical handling. If authorised, demonstrate under direct teacher observation; otherwise report the plan without claiming performance.', 'Dans un autre jardin autorisé, adapte seul un plan aux consignes documentées et explique les changements de manipulation. Si l’action est autorisée, démontre-la sous observation ; sinon présente uniquement le plan sans prétendre l’avoir réalisé.')],
    retention: [tx('Can colour alone establish a fertiliser’s safe dose?', 'La couleur seule peut-elle déterminer une dose d’engrais sûre ?'), tx('What is the correct status when only a paper application model was completed?', 'Quel statut convient lorsque seul un modèle papier d’application est terminé ?')],
    retentionOptions: [{ en: ['No; verified product/crop guidance is needed', 'Yes; all similar colours mean the same dose', 'Yes; containers determine every dose'], fr: ['Non ; il faut des consignes vérifiées de produit/culture', 'Oui ; des couleurs semblables imposent la même dose', 'Oui ; les récipients déterminent toute dose'] }, { en: ['Practical performance remains pending', 'All field skills are independently mastered', 'A model is identical to real application'], fr: ['La réalisation pratique reste en attente', 'Toutes les compétences de terrain sont maîtrisées', 'Un modèle équivaut à une vraie application'] }],
    criteria: [tx('Inspect physical-property explanations and checked material/crop instructions; require actual directly observed permitted application for practical credit.', 'Examiner propriétés et consignes vérifiées ; exiger une vraie application autorisée directement observée pour toute validation pratique.'), tx('Distinguish individual work from group support and paper simulation; unavailable or unsafe operations remain pending rather than receiving a correct practical judgement.', 'Distinguer travail individuel, aide de groupe et simulation ; les opérations impossibles ou dangereuses restent en attente sans validation pratique.')],
  }),
  unit(49, 1, {
    title: tx('Observing domestic animals and identifying breeds', 'Observer les animaux domestiques et identifier les races'),
    subskills: ['identify-domestic-animals', 'record-observable-characteristics', 'match-verified-breeds'], misconception: 'infers-a-breed-from-colour-alone',
    explanation: tx('Domestic animals are kept and managed by people. In Ghanaian communities these may include goats, sheep, cattle, pigs, chickens, ducks and others. Describe observable shape, size, covering, colour and feeding behaviour while keeping a safe distance with an adult. A breed is a population within a domestic animal type with inherited characteristics; a goat is not itself a breed name. Colour alone is not reliable breed evidence. For example, West African Dwarf is a recognised goat breed, but do not assign it to every small local goat: check a trusted breed reference or an informed keeper. Record uncertainty and never invent an animal observation.', 'Les animaux domestiques sont élevés et gérés par les humains. Au Ghana, on peut rencontrer chèvres, moutons, bovins, porcs, poules, canards et d’autres animaux. Décris forme, taille, revêtement, couleur et alimentation à distance sûre avec un adulte. Une race est une population au sein d’un type d’animal domestique avec des caractères hérités ; « chèvre » n’est pas un nom de race. La couleur seule ne suffit pas. La chèvre naine d’Afrique de l’Ouest est une race reconnue, mais toute petite chèvre locale n’en relève pas nécessairement : vérifie avec une référence fiable ou un éleveur informé. Note l’incertitude sans inventer d’observation.'),
    example: tx('Use a record with columns animal, date/place or approved image source, shape/size/covering, observed feeding, suggested breed and supporting reference. If a keeper identifies a breed, label that as a report and check it where possible. “Brown goat; breed not verified” is more honest than a confident invented breed. Do not approach unfamiliar livestock or handle feed/manure.', 'Utilise les colonnes animal, date/lieu ou source d’image, forme/taille/revêtement, alimentation observée, race proposée et référence. Si un éleveur nomme une race, note ce témoignage et vérifie-le si possible. « Chèvre brune ; race non vérifiée » vaut mieux qu’une race inventée. N’approche pas un animal inconnu et ne manipule ni aliments ni fumier.'),
    question: tx('Which record is justified when only a goat’s colour was observed?', 'Quelle note est justifiée si seule la couleur d’une chèvre a été observée ?'),
    options: { en: ['Brown goat; breed not verified', 'Brown colour proves one exact breed', 'Every goat is the same breed'], fr: ['Chèvre brune ; race non vérifiée', 'La couleur brune prouve une race précise', 'Toutes les chèvres sont de la même race'] },
    correction: tx('Separate an observed characteristic from an inferred breed. Colour is a description, not sufficient breed proof. Record what you saw and identify the reference needed before matching the breed. Then retry.', 'Distingue caractéristique observée et race supposée. La couleur décrit l’animal sans prouver sa race. Note ce qui est vu et la référence nécessaire, puis réessaie.'),
    tasks: [tx('With permission and adult supervision, identify domestic animals genuinely available in a defined community area or approved documented image set. Independently record characteristics and feeding, then match animals to breeds using checked references/keeper evidence, marking uncertainty. Show the actual records and explain your classifications to your teacher.', 'Avec permission et supervision, identifie les animaux réellement présents dans un périmètre défini ou un jeu d’images documenté approuvé. Note seul caractères et alimentation, puis associe les races à l’aide de références/témoignages vérifiés, en signalant les incertitudes. Présente les vraies notes et explique les classements.'), tx('Prepare your own comparison of at least two teacher-approved domestic animal types and verified breed examples. Explain shape, covering, size and feeding evidence, distinguishing direct observations, image evidence and reports. Teacher review must check the references and actual product.', 'Prépare une comparaison personnelle d’au moins deux types approuvés et d’exemples de races vérifiés. Explique forme, revêtement, taille et alimentation en distinguant observation, image et témoignage. L’enseignant vérifie références et vrai travail.')],
    transfer: [tx('For a new approved animal/image, independently describe it before suggesting a breed. Explain what evidence would confirm or reject the suggestion and keep the breed unverified where evidence is missing.', 'Pour un nouvel animal ou une image approuvée, décris-le seul avant de proposer une race. Explique les preuves utiles et garde la race non vérifiée si elles manquent.'), tx('Evaluate a community animal list that confuses animal types with breed names. Correct it using checked references, explain each change and preserve observations rather than replacing them with guesses.', 'Évalue une liste confondant types d’animaux et races. Corrige-la avec des références vérifiées, explique chaque changement et conserve les observations sans les remplacer par des suppositions.')],
    retention: [tx('What does a breed identify in this context?', 'Que désigne une race dans ce contexte ?'), tx('How should an unconfirmed keeper statement be recorded?', 'Comment noter une déclaration d’éleveur non confirmée ?')],
    retentionOptions: [{ en: ['An inherited-characteristic population within an animal type', 'Every animal of the same colour', 'The word goat by itself'], fr: ['Une population aux caractères hérités au sein d’un type d’animal', 'Tous les animaux d’une même couleur', 'Le seul mot chèvre'] }, { en: ['As a report needing verification', 'As a direct observation I did not make', 'As certain merely because it was repeated'], fr: ['Comme un témoignage à vérifier', 'Comme une observation que je n’ai pas faite', 'Comme une certitude parce qu’elle est répétée'] }],
    criteria: [tx('Inspect genuine animal/characteristic records and checked breed matching, distinguishing types from breeds.', 'Examiner les vrais relevés et les associations de races vérifiées, en distinguant type et race.'), tx('Require independent classification reasoning, evidence labels and honest uncertainty without unsafe animal contact.', 'Exiger classement raisonné autonome, nature des preuves et incertitude honnête, sans contact dangereux.')],
  }),
  unit(50, 1, {
    title: tx('Comparing ruminants, monogastrics and poultry', 'Comparer ruminants, monogastriques et volailles'),
    subskills: ['classify-livestock-with-evidence', 'compare-digestive-and-body-features', 'compare-across-contexts'], misconception: 'treats-poultry-as-always-herbivorous-or-mutually-exclusive',
    explanation: tx('Ruminants such as cattle, goats and sheep have a specialised stomach with compartments and regurgitate and rechew cud. A pig is an example of a non-ruminant monogastric mammal with a simple stomach. Poultry are domesticated birds such as chickens and ducks, with feathers, beaks and egg laying. These labels are useful farming categories, but do not form perfectly separate scientific sets: birds have specialised digestive systems and chickens can eat both plant and animal food. Do not describe all poultry as herbivores. Similarities include needing food, water and appropriate care; differences include body covering, reproduction, digestive structures and feeding. Compare documented animals in Ghana and another country without assuming location changes the basic category.', 'Les ruminants, comme bovins, chèvres et moutons, possèdent un estomac compartimenté et régurgitent pour remâcher. Le porc est un mammifère monogastrique non ruminant à estomac simple. Les volailles sont des oiseaux domestiques, comme poules et canards, portant plumes et bec et pondant des œufs. Ces catégories d’élevage ne sont pas des ensembles scientifiques parfaitement exclusifs : les oiseaux ont un appareil digestif spécialisé et les poules peuvent manger des aliments végétaux et animaux. Ne qualifie pas toutes les volailles d’herbivores. Compare besoins communs, revêtement, reproduction, digestion et alimentation, au Ghana et ailleurs, sans supposer que le pays change la catégorie.'),
    example: tx('Build a comparison table: goat — ruminant, hair, live young, cud chewing; pig — non-ruminant monogastric mammal, hair, live young, no rumination; chicken — poultry, feathers, eggs, specialised bird digestion. Add their shared needs. Use checked pictures/descriptions, not attempts to inspect an animal’s stomach.', 'Construis un tableau : chèvre — ruminant, poils, petits vivants, rumination ; porc — mammifère monogastrique non ruminant, poils, petits vivants, sans rumination ; poule — volaille, plumes, œufs, digestion d’oiseau spécialisée. Ajoute les besoins communs. Utilise des descriptions/images vérifiées sans examiner physiquement un estomac.'),
    question: tx('Which animal is a ruminant in the comparison?', 'Quel animal est ruminant dans la comparaison ?'),
    options: { en: ['Goat', 'Pig', 'Chicken'], fr: ['La chèvre', 'Le porc', 'La poule'] },
    correction: tx('Use digestive evidence, not just diet or size. The goat chews cud and is a ruminant. The pig is a non-ruminant monogastric mammal; the chicken belongs to poultry. Eating plant food alone does not make an animal a ruminant. Retry with that evidence.', 'Utilise la digestion, pas seulement le régime ou la taille. La chèvre rumine ; le porc est un mammifère monogastrique non ruminant ; la poule est une volaille. Manger des végétaux ne suffit pas à être ruminant. Réessaie avec ces preuves.'),
    tasks: [tx('Independently classify checked examples of cattle/goat/sheep, pig and chicken/duck into the source’s farming categories. Write similarities and differences in covering, reproduction, feeding and digestive features. Compare documented Ghanaian examples with examples from another country using cited references. Explain category overlap and avoid the claim that all poultry are herbivores. Teacher review is required.', 'Classe seul des exemples vérifiés de bovin/chèvre/mouton, porc et poule/canard dans les catégories d’élevage de la source. Rédige points communs et différences : revêtement, reproduction, alimentation, digestion. Compare des exemples ghanéens et d’un autre pays avec références. Explique les recoupements sans dire que toute volaille est herbivore. Examen requis.'), tx('Create your own comparison table and oral explanation for a new teacher-selected set of domestic animals, including all three categories. Give evidence for each classification and written similarities across Ghana and another country; distinguish physical observations from reference facts.', 'Crée ton tableau et explique oralement un nouvel ensemble choisi par l’enseignant, couvrant les trois catégories. Justifie les classements et rédige les ressemblances entre Ghana et autre pays, en distinguant observations et faits documentés.')],
    transfer: [tx('Correct a fictional poster claiming all plant-eating animals are ruminants and all poultry are herbivores. Use checked examples and your own comparison chart to explain both errors.', 'Corrige une affiche affirmant que tout animal mangeant des plantes est ruminant et toute volaille herbivore. Appuie-toi sur des exemples vérifiés et ton propre tableau.'), tx('Use teacher-provided information about an unfamiliar domestic animal to explain which farming category fits and what further digestive/reproductive evidence is needed. Compare it with a known example without classifying by country alone.', 'Avec des informations fournies sur un animal domestique inhabituel, explique la catégorie adaptée et les preuves digestives/reproductives nécessaires. Compare-le à un exemple connu sans le classer seulement par pays.')],
    retention: [tx('Which feature supports identifying a ruminant?', 'Quelle caractéristique aide à identifier un ruminant ?'), tx('Which statement about chickens is scientifically accurate?', 'Quelle affirmation sur les poules est scientifiquement exacte ?')],
    retentionOptions: [{ en: ['Regurgitating and rechewing cud with specialised digestion', 'Simply having brown hair', 'Living in Ghana rather than elsewhere'], fr: ['Régurgiter et remâcher avec une digestion spécialisée', 'Avoir seulement des poils bruns', 'Vivre au Ghana plutôt qu’ailleurs'] }, { en: ['They are poultry and may eat plant and animal foods', 'All poultry are necessarily herbivores', 'They are ruminants because they eat grain'], fr: ['Ce sont des volailles pouvant manger végétaux et aliments animaux', 'Toute volaille est nécessairement herbivore', 'Elles sont ruminantes parce qu’elles mangent du grain'] }],
    criteria: [tx('Inspect actual written comparisons and evidence-based classification, including Ghana/other-country examples.', 'Examiner les vraies comparaisons écrites et classements justifiés, avec exemples du Ghana et d’un autre pays.'), tx('Check digestive distinctions and category overlap; do not endorse the printed parenthetical implying poultry are universally herbivorous.', 'Vérifier distinctions digestives et recoupements ; ne pas approuver la parenthèse imprimée suggérant que toute volaille est herbivore.')],
  }),
  unit(51, 1, {
    title: tx('Domestic and commercial uses of animals', 'Usages familiaux et commerciaux des animaux'),
    subskills: ['distinguish-household-and-commercial-purpose', 'compare-uses-across-animal-categories', 'create-evidence-based-poster'], misconception: 'assumes-a-product-determines-purpose-without-context',
    explanation: tx('A domestic or household use meets a household’s needs; a commercial use produces goods or services for sale or income. The same animal product can have either purpose. Eggs eaten at home serve a household use; eggs sold at a market serve a commercial use. Ruminants, monogastric mammals and poultry have different possible uses, but actual uses vary with community, culture, management and the specific animal. Do not assume every cow produces saleable milk or every animal provides every product. A useful poster names the animal, its supported use and the household/commercial context. Treat animals humanely and do not carry out production or slaughter for this lesson.', 'Un usage domestique répond aux besoins du foyer ; un usage commercial fournit des biens ou services destinés à la vente ou au revenu. Un même produit peut servir les deux buts. Des œufs consommés au foyer ont un usage domestique ; vendus au marché, un usage commercial. Ruminants, mammifères monogastriques et volailles ont des usages possibles différents, qui varient selon communauté, culture, gestion et animal. Ne suppose pas que chaque vache fournit du lait commercialisable ou chaque animal tous les produits. Une bonne affiche nomme l’animal, l’usage documenté et son contexte familial/commercial. Respecte les animaux ; aucune production ni mise à mort n’est demandée.'),
    example: tx('Make a two-animal poster using a goat and a chicken from checked information. For the chicken, distinguish eggs consumed by a household from eggs sold. For the goat, include only a genuinely supported use from your source. Add a short written comparison covering ruminants, non-ruminant monogastrics and poultry, noting where another animal example is needed.', 'Fais une affiche sur une chèvre et une poule à partir d’informations vérifiées. Distingue les œufs consommés et vendus. Pour la chèvre, ne retiens qu’un usage réellement appuyé par la source. Ajoute une comparaison des ruminants, monogastriques non ruminants et volailles, en indiquant si un autre exemple est nécessaire.'),
    question: tx('The same hen’s eggs are eaten at home and sold at market. What distinguishes the uses?', 'Les œufs d’une même poule sont consommés au foyer et vendus au marché. Qu’est-ce qui distingue ces usages ?'),
    options: { en: ['Household consumption versus sale for income', 'The eggs must be different animal species', 'Every use is commercial even without sale'], fr: ['La consommation familiale et la vente pour un revenu', 'Les œufs proviennent forcément d’espèces différentes', 'Tout usage est commercial même sans vente'] },
    correction: tx('Identify the purpose, not only the product. Eating eggs at home meets household needs; selling eggs produces income. The product can be the same. State the purpose in each case and retry.', 'Repère le but, pas seulement le produit. Manger les œufs répond à un besoin familial ; les vendre apporte un revenu. Le produit peut être identique. Précise le but de chaque cas et réessaie.'),
    tasks: [tx('Independently make a real illustrated poster about any two useful domestic animals, citing checked information. Explain household and commercial use and write a comparison including examples of ruminants, non-ruminant monogastrics and poultry. Distinguish possible uses from locally observed ones. Your teacher must inspect the actual poster and written explanation.', 'Réalise seul une vraie affiche illustrée sur deux animaux domestiques utiles avec sources vérifiées. Explique usages familiaux/commerciaux et rédige une comparaison incluant ruminants, monogastriques non ruminants et volailles. Distingue usages possibles et observés localement. L’enseignant examine affiche et texte.'), tx('Create a different two-animal poster and independent written discussion showing how purpose changes the classification of a use. Cover all three farming categories in your discussion, justify each example with a source and explain limitations to your teacher.', 'Crée une autre affiche sur deux animaux et un texte personnel montrant comment le but change la catégorie d’usage. Couvre les trois catégories dans la discussion, justifie les exemples avec une source et explique les limites à l’enseignant.')],
    transfer: [tx('A fictional family keeps some animal products and sells the rest. Independently classify the uses, explain why product name alone is insufficient and design a new informative poster without inventing real household data.', 'Une famille fictive garde une partie des produits et vend le reste. Classe seul les usages, explique pourquoi le nom du produit ne suffit pas et conçois une nouvelle affiche sans inventer de données familiales réelles.'), tx('Evaluate a poster claiming every domestic animal has identical commercial uses. Revise it with checked examples from different animal categories and explain how context changes the purpose.', 'Évalue une affiche attribuant des usages commerciaux identiques à tous les animaux. Corrige-la avec des exemples vérifiés de différentes catégories et explique le rôle du contexte.')],
    retention: [tx('Which use is commercial in the stated context?', 'Quel usage est commercial dans le contexte indiqué ?'), tx('What makes a two-animal poster educationally defensible?', 'Qu’est-ce qui rend une affiche sur deux animaux justifiable ?')],
    retentionOptions: [{ en: ['Selling documented animal products for income', 'Eating household eggs without sale', 'Only drawing the animal'], fr: ['Vendre des produits animaux documentés pour un revenu', 'Manger les œufs du foyer sans vente', 'Dessiner seulement l’animal'] }, { en: ['Checked animal-use examples with clear purposes', 'Assigning every product to every animal', 'Invented observations presented as real'], fr: ['Des usages vérifiés avec des buts explicites', 'Attribuer chaque produit à chaque animal', 'Présenter des observations inventées comme réelles'] }],
    criteria: [tx('Inspect the actual two-animal poster and independent discussion across ruminants, monogastrics and poultry.', 'Examiner la vraie affiche et la discussion autonome couvrant ruminants, monogastriques et volailles.'), tx('Check household/commercial purpose and evidence for each use; reject unsupported universal products or invented observations.', 'Vérifier but familial/commercial et preuves ; refuser produits universels non justifiés et observations inventées.')],
  }),
  unit(52, 1, {
    title: tx('Investigating animal uses and by-products locally', 'Enquêter sur les usages et sous-produits animaux locaux'),
    subskills: ['conduct-scoped-observation-research', 'match-animals-products-and-byproducts', 'compare-uses-with-evidence'], misconception: 'reports-an-interview-or-observation-that-did-not-occur',
    explanation: tx('An investigation begins with a question, permission and a safe observation plan. Record the domestic animals actually observed, dates/locations without personal details, their observed uses and any keeper explanations clearly labelled as reports. Commercial uses include supported products/services and by-products; suitably managed animal waste may be used as manure, but raw waste is not harmless and no handling is required here. Match each animal to an evidenced use and compare similarities and differences. Do not infer a commercial activity merely from seeing an animal, and never invent an interview, sale, product or survey result. A small survey describes its scope, not every community.', 'Une enquête commence par une question, une autorisation et un plan sûr. Note les animaux réellement observés, dates/lieux sans données personnelles, usages vus et explications d’éleveurs clairement signalées comme témoignages. Les usages commerciaux comprennent produits/services et sous-produits documentés ; des déjections correctement gérées peuvent servir d’amendement, sans être inoffensives à l’état brut. Aucun contact n’est nécessaire ici. Associe chaque animal à un usage prouvé et compare points communs et différences. Voir un animal ne prouve pas une vente. N’invente ni entretien, produit ni résultat. Une petite enquête ne représente que son périmètre.'),
    example: tx('Prepare a blank table: animal → observed use → reported use → product/by-product → evidence/source → uncertainty. In a fictional worked row, “chicken → eggs reported for sale” remains a keeper report until verified; seeing a chicken does not prove sales. In your real investigation replace the fictional row with genuine evidence and keep any unavailable product unverified. Never touch manure or enter animal enclosures.', 'Prépare un tableau vide : animal → usage observé → usage rapporté → produit/sous-produit → preuve/source → incertitude. Dans une ligne fictive, « poule → œufs déclarés vendus » reste un témoignage tant qu’il n’est pas vérifié ; voir la poule ne prouve pas la vente. Dans l’enquête réelle, remplace l’exemple fictif par de vraies preuves et garde les données absentes non vérifiées. Ne touche pas aux déjections et n’entre pas dans les enclos.'),
    question: tx('You see a goat but do not observe or verify any sale. Which conclusion is justified?', 'Tu vois une chèvre sans observer ni vérifier de vente. Quelle conclusion est justifiée ?'),
    options: { en: ['The goat was observed; its commercial use is not yet verified', 'A sale definitely happened', 'Every possible goat product was observed'], fr: ['La chèvre a été observée ; son usage commercial reste à vérifier', 'Une vente a certainement eu lieu', 'Tous les produits possibles ont été observés'] },
    correction: tx('Separate the sighting from the conclusion. An observed animal is evidence of its presence, not proof of a sale or by-product use. Record the observation and the remaining question. Retry without inventing an event.', 'Distingue présence et conclusion. Voir l’animal prouve sa présence, pas une vente ou l’usage d’un sous-produit. Note l’observation et la question restante, puis réessaie sans inventer d’événement.'),
    tasks: [tx('With adult permission and safe supervision, conduct a scoped observation investigation of domestic animals in your community. Independently list and compare their uses, matching animals to documented commercial products and by-products including a checked animal-waste use. Distinguish observed, reported and unverified facts. Submit genuine dated notes and your comparison; your teacher checks the actual investigation. No waste handling or personal data collection.', 'Avec permission et supervision, mène une enquête délimitée d’observation d’animaux domestiques dans ta communauté. Liste et compare seul les usages, en associant produits commerciaux et sous-produits documentés, dont un usage vérifié des déjections. Distingue observation, témoignage et incertitude. Présente tes vraies notes datées et la comparaison ; l’enseignant vérifie l’enquête. Ni manipulation de déchets ni données personnelles.'), tx('Investigate another approved animal-use question with genuine observations or permitted documented records. Produce an independent animal/product/by-product table, explain commercial matches and compare with your first findings without extending beyond the evidence. Teacher inspection of original notes is required.', 'Étudie une autre question autorisée avec de vraies observations ou documents permis. Produis seul un tableau animaux/produits/sous-produits, explique les associations commerciales et compare avec tes premiers résultats sans dépasser les preuves. L’enseignant examine les notes originales.')],
    transfer: [tx('A new school report lists animal sales that were never observed or verified. Independently identify the unsupported claims, redesign the evidence table and specify safe ways to check uses and by-products. Do not report the redesigned investigation as already completed.', 'Un nouveau rapport mentionne des ventes jamais observées ni vérifiées. Repère seul ces affirmations, refais le tableau de preuves et propose des vérifications sûres des usages/sous-produits. Ne présente pas ce projet d’enquête comme déjà réalisé.'), tx('Compare findings from your genuine survey with a teacher-provided report from another community. Explain shared and different animal uses, evidence quality and limits of generalisation. Support every claim with a clearly identified record.', 'Compare ta vraie enquête à un rapport fourni d’une autre communauté. Explique usages communs/différents, qualité des preuves et limites de généralisation. Appuie chaque affirmation sur un document identifié.')],
    retention: [tx('What is an appropriate example of an animal by-product use to investigate?', 'Quel exemple d’usage d’un sous-produit animal peut-on étudier ?'), tx('What must an observation report distinguish?', 'Que doit distinguer un rapport d’observation ?')],
    retentionOptions: [{ en: ['Verified use of suitably managed waste as manure', 'An invented sale presented as observed', 'Every waste material as automatically safe'], fr: ['Un usage vérifié de déjections correctement gérées comme amendement', 'Une vente inventée présentée comme observée', 'Tout déchet considéré automatiquement inoffensif'] }, { en: ['Observed, reported and unverified information', 'Only confident-sounding guesses', 'Every community treated as identical'], fr: ['Informations observées, rapportées et non vérifiées', 'Seulement les suppositions assurées', 'Toutes les communautés supposées identiques'] }],
    criteria: [tx('Inspect genuine original investigation notes and independent evidence-labelled comparisons of animal uses/products/by-products.', 'Examiner les vraies notes originales et les comparaisons autonomes des usages/produits/sous-produits avec preuves.'), tx('Check scope, commercial matches, actual observations and limitations; reject fabricated fieldwork or implied safe raw-waste handling.', 'Vérifier périmètre, associations commerciales, observations réelles et limites ; refuser enquête fictive ou manipulation de déchets bruts présentée comme sûre.')],
  }),
);
